alter policy projects_admin_delete on public.projects using(public.is_admin() and deleted_at is not null and not exists(select 1 from public.payment_documents d where d.project_id=projects.id) and not exists(select 1 from public.payment_requests r where r.project_id=projects.id and r.stripe_locked and r.status not in ('paid','cancelled')));
create policy project_quotes_active_insert on public.project_quotes as restrictive for insert to authenticated with check(exists(select 1 from public.projects p where p.id=project_id and p.archived_at is null and p.deleted_at is null));
create policy project_quotes_active_update on public.project_quotes as restrictive for update to authenticated using(exists(select 1 from public.projects p where p.id=project_id and p.archived_at is null and p.deleted_at is null)) with check(exists(select 1 from public.projects p where p.id=project_id and p.archived_at is null and p.deleted_at is null));
