create policy project_storage_active_insert on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'project-files' or (storage.foldername(name))[1]='avatars' or exists(select 1 from public.projects p where p.id::text=(storage.foldername(name))[1] and p.archived_at is null and p.deleted_at is null));
